<script setup lang="ts">import {ref,computed} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';import ProfileMatrix from '../components/ProfileMatrix.vue';import {catalogApi} from '../api/catalog';import {useTask} from '../hooks/useTask';import {formatMarks} from '../utils/constraints';const p=defineProps<{studies:any[];traces:any[];profiles:any[];user:any;reloadCatalog:()=>Promise<void>}>(),id=ref(0),raw=ref(JSON.stringify({name:'三步观测手算研究',filename:'yx-three-token-fixture.json',description:'固定二态三观测码的独立手算校验',symbols:['0','1','2'],traces:[{reference:'HAND-001',tokens:['0','1','2'],constraints:[]}]},null,2)),task=useTask(),study=computed(()=>p.studies.find(s=>s.id===(id.value||p.studies[0]?.id))),rows=computed(()=>p.traces.filter(t=>t.study_id===study.value?.id)),models=computed(()=>p.profiles.filter(m=>m.study_id===study.value?.id));async function create(){await task.act(async()=>{const s=await catalogApi.createStudy(JSON.parse(raw.value));await p.reloadCatalog();id.value=s.id},'观测研究已保存，可冻结固定模型')}function revise(t:any){const text=prompt('按空格输入观测码',t.tokens.join(' '));if(text!==null){const next=tokens(text);const stateCount=stateCountOf(t);task.act(async()=>{await catalogApi.editTrace(t.id,next,undefined,next.length,stateCount)},'轨迹已修订，既有任务保留提交时快照')}}function tokens(text:string){return text.trim().split(/\s+/.test(text)?/\s+/:/,/).filter(Boolean)}function stateCountOf(t:any){const model=models.value.find((m:any)=>m.parameters?.pi?.length)||models.value[0];return model?model.parameters.pi.length:3}function mark(t:any){const text=prompt('逐时刻标记隐态假设（1-based步:0-based状态索引，如 2:0,1），留空清除标记',formatMarks(t.constraints));if(text!==null)task.act(async()=>{await catalogApi.editTrace(t.id,undefined,text.trim(),t.tokens.length,stateCountOf(t))},'隐态标记已保存；已冻结队列的输入不受影响')}async function clear(t:any){await task.act(async()=>{await catalogApi.editTrace(t.id,undefined,'',t.tokens.length,stateCountOf(t))},'标记已清除，本条恢复无约束推断')}</script><template><PageTitle index="02" title="先核对观测码，再核对模型版本。" description="字母表固定；相同模型标签不等于设备真实工况。逐时刻的隐态假设在此标记，随轨道进入冻结输入。"/><label>来源研究<select :value="study?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p v-if="study">{{study.filename}} / {{study.description}} / 观测码{{study.symbols.join(' / ')}}</p><div class="source-layout"><section><h2>观测底稿 / 前20条</h2><Table :headers="['轨迹编号','码数','观测片段','隐态标记','修订']"><tr v-for="t in rows.slice(0,20)" :key="t.id"><td>{{t.reference}}</td><td>{{t.tokens.length}}</td><td class="tokens">{{t.tokens.slice(0,24).join(' ')}}{{t.tokens.length>24?' …':''}}</td><td class="mark-text">{{formatMarks(t.constraints)||'无约束'}}<small v-if="!t.constraints?.length">旧数据或未标记：按无约束读取</small></td><td class="row-actions"><button v-if="user.role!=='viewer'" @click="revise(t)">修订</button><button v-if="user.role!=='viewer'" @click="mark(t)">标记隐态</button><button v-if="user.role!=='viewer'&&t.constraints?.length" @click="clear(t)">清除</button></td></tr></Table><p class="hint">标记输入形如 <code>2:0,1; 4:2</code>：第2步只允许状态0/1，第4步只允许状态2。只标记有待核对的时刻，其余时刻保持无约束；推断时后验与联合路径都在同一标记约束下计算。</p></section><section class="input-panel"><small>NEW OBSERVATION STUDY</small><h2>导入已编码轨迹</h2><p>声明2–6观测码；每研究1–240条，每条1–200码。推断任务另限最多30条。可选的 constraints 数组记录逐时刻隐态假设。</p><form v-if="user.role!=='viewer'" @submit.prevent="create"><label>观测 JSON<textarea v-model="raw" rows="17"/></label><button class="primary" :disabled="task.state.busy">保存观测研究 →</button></form><p v-else>观察员只读底稿。</p><Notice v-bind="task.state"/></section></div><ProfileMatrix v-for="model in models" :key="model.id" :profile="model"/></template>
